@push('scripts')
<script>
(() => {
    const apiUrl = @json(route('riser.details', ['id' => '__ID__'])).replace('__ID__', String(@json($riser->id)));
    const mapDefinition = @json($baseMap);
    const setText = (id, value) => { const element = document.getElementById(id); if (element) element.textContent = value ?? '—'; };
    const alertBox = document.getElementById('riser-page-alert');
    const showError = message => { if (!alertBox) return; alertBox.textContent = message; alertBox.className = 'alert alert-danger mt-3'; };
    const statusLabels = {flagRiser:'نشانه‌گذاری‌شده', repair:'در حال تعمیر', submitted:'ارسال‌شده', completed:'تکمیل‌شده'};
    const renderActions = data => { const panel=document.getElementById('riser-actions-panel'); if(!panel)return; panel.replaceChildren(); const item=data.open_case; if(!item){const empty=document.createElement('span');empty.className='text-muted small';empty.textContent='پرونده جاری برای این علمک وجود ندارد.';panel.append(empty);return;} const actions=[]; if(item.operations_create_url)actions.push(['ثبت گروهی تعمیرات',item.operations_create_url,'btn-primary']); if(item.operations_edit_url)actions.push(['ویرایش گروهی تعمیرات',item.operations_edit_url,'btn-outline-primary']); actions.forEach(([label,url,kind])=>{const link=document.createElement('a');link.href=url;link.className='btn '+kind+' rp-btn';link.textContent=label;panel.append(link);}); if(!actions.length){const message=document.createElement('div');message.className='alert alert-warning mb-0';message.textContent='ویرایش یا ثبت عملیات در وضعیت فعلی برای کاربر شما مجاز نیست.';panel.append(message);}};
    const renderSummary = data => { const status=statusLabels[data.status]||data.status||'نامشخص'; setText('riser-page-code',data.code||@json($riser->id)); setText('riser-fact-code',data.code||'—'); setText('riser-page-status',status); setText('riser-fact-status',status); setText('riser-fact-organization',data.organization_name||'—'); setText('riser-context-organization',data.organization_name||'—'); setText('riser-context-zone',data.zone_name||'—'); setText('riser-zone-badge',data.zone_name||'Zone نامشخص'); setText('riser-context-updated',data.updated_at||'—'); const c=data.coordinate?.coordinates; const valid=Array.isArray(c)&&c.length>=2; setText('riser-fact-coordinate',valid?Number(c[1]).toFixed(5)+', '+Number(c[0]).toFixed(5):'ثبت نشده'); setText('riser-location-text',valid?'مختصات معتبر علمک روی نقشه نمایش داده شده است.':'برای این علمک مختصات معتبر ثبت نشده است.'); const state=document.getElementById('riser-case-state'); if(state)state.textContent=data.open_case?'پرونده #'+data.open_case.id+' · '+(statusLabels[data.open_case.status]||data.open_case.status):'پرونده جاری وجود ندارد.'; renderActions(data); };
    const renderMap = data => { const target=document.getElementById('riser-map'); const c=data.coordinate?.coordinates; const lng=Number(c?.[0]); const lat=Number(c?.[1]); if(!target||!window.ol||!Number.isFinite(lng)||!Number.isFinite(lat)||lng<-180||lng>180||lat<-90||lat>90){if(target)target.textContent='هندسه یا مختصات معتبر برای نمایش نقشه وجود ندارد.';return;} if(!mapDefinition?.tile_url){target.textContent='پروفایل فعال GIS برای نمایش نقشه پیدا نشد.';return;} const point=ol.proj.fromLonLat([lng,lat]); const marker=new ol.Feature({geometry:new ol.geom.Point(point)}); marker.setStyle(new ol.style.Style({image:new ol.style.Circle({radius:8,fill:new ol.style.Fill({color:'#dc3545'}),stroke:new ol.style.Stroke({color:'#fff',width:2})})})); const markerLayer=new ol.layer.Vector({source:new ol.source.Vector({features:[marker]})}); const base=mapDefinition.service_type==='vector_mvt'?new ol.layer.VectorTile({source:new ol.source.VectorTile({format:new ol.format.MVT(),url:mapDefinition.tile_url})}):new ol.layer.Tile({source:new ol.source.XYZ({url:mapDefinition.tile_url,attributions:mapDefinition.attribution||undefined})}); const map=new ol.Map({target,layers:[base,markerLayer],view:new ol.View({center:point,zoom:16,minZoom:mapDefinition.min_zoom,maxZoom:mapDefinition.max_zoom}),interactions:ol.interaction.defaults.defaults({mouseWheelZoom:false})}); window.addEventListener('resize',()=>map.updateSize(),{passive:true}); requestAnimationFrame(()=>map.updateSize()); base.getSource()?.on('tileloaderror',()=>{const box=document.getElementById('riser-map-alert');if(box){box.textContent='Tile Server نقشه در دسترس نیست.';box.classList.remove('d-none');}}); };
    fetch(apiUrl,{headers:{Accept:'application/json'}}).then(response=>{if(!response.ok)throw new Error('دریافت اطلاعات علمک انجام نشد.');return response.json();}).then(data=>{renderSummary(data);renderMap(data);}).catch(error=>showError(error.message||'خطا در دریافت اطلاعات علمک.'));
})();
</script>
@endpush
